// Source geometry is mapped per bone, retaining relationships and the palmar overlay
// of the pisiform. See assets/anatomy/NOTICE.md for provenance and licenses.
for(const [plate,art] of [[hand,handArtwork],[foot,footArtwork],[leg,legArtwork]] as const){
 const data=art as Record<string,{shapes:Shape[];anchor:number[]}>;
 for(const p of plate.parts){const a=data[p.id];if(a){p.shapes=a.shapes;p.anchor=a.anchor as [number,number];}}
 plate.details=[];
 // Draw broad posterior bones first and smaller overlapping structures last.
 const order=plate.id==='hand'?['radius','ulna','mc1','mc2','mc3','mc4','mc5','scaphoid','lunate','triquetrum','trapezium','trapezoid','capitate','hamate','pisiform']:plate.id==='foot'?['calcaneus','talus','navicular','cuboid','medial-cuneiform','intermediate-cuneiform','lateral-cuneiform']:['femur','fibula','tibia','patella'];
 plate.parts.sort((a,b)=>(order.includes(a.id)?order.indexOf(a.id):100)-(order.includes(b.id)?order.indexOf(b.id):100));
}
regions.push(...(respiratoryRegionData as unknown as Region[]),...advancedRegions,...clinicalRegions);
for(const r of regions){const plate=(detailedPlates as unknown as Record<string,DetailedPlate>)[r.id];if(plate){r.detailedPlate=plate;r.view=plate.view;for(const p of r.parts){if(plate.anchors[p.id])p.anchor=plate.anchors[p.id];}}}
export const allParts=regions.flatMap(r=>r.parts.map(p=>({...p,key:`${r.id}/${p.id}`,regionId:r.id})));
export type StudyPart=typeof allParts[number];
export const normalize=(s:string)=>s.normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');
export const accepts=(p:Part,answer:string)=>[p.name,...p.aliases].some(n=>normalize(n)===normalize(answer));
export const partByKey=(key:string)=>allParts.find(p=>p.key===key);
export const groups=['All regions','Head & neck','Upper limb','Thorax','Trunk','Abdomen & pelvis','Lower limb','Surface anatomy'];
